def countBallotPaths(a, b):
    MOD = 1000000007
    N = a + b
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * pow(fact[k] * fact[n - k] % MOD, MOD - 2, MOD) % MOD

    return (C(N, b) - C(N, b - 1)) % MOD
